export const BODY: string = "\n<p>إزالة بيانات صورة وصفية تستغرق أقل من دقيقة: ترفع الصورة وتزيل الأداة البيانات المخفية وتنزّل نسخة نظيفة.</p>\n<p>يمر هذا الدليل بكل خطوة مع أداة إزالة البيانات الوصفية المجانية: تعمل في متصفحك ولا تطلب حسابًا ولا ترفع صورك إلى أي مكان أبدًا.</p>\n<p>في النهاية ستعرف كيف تنظف صورة وتنظف دفعة كاملة وتختار طريقة التنظيف الصحيحة وتثبت أن النتيجة نظيفة.</p>\n<h2 id=\"what-you-need\">ما تحتاجه قبل أن تبدأ</h2>\n<p>تحتاج ملف الصورة الذي تنوي مشاركته، محفوظًا على جهازك: اعمل مع الملف الأصلي، لا مع نسخة نشرتها في مكان ما بالفعل. وتقبل الأداة ملفات JPG وPNG وWebP وHEIC حتى 20 MB لكل ملف: هذا يغطي صور الهاتف وJPEG كاميرات DSLR وتصديرات PNG وملفات HEIC من iPhone.</p>\n<p>احفظ نسخة خاصة من الأصل إذا همتك البيانات الوصفية: التنظيف دائم للنسخة النظيفة، وضبط الكاميرا وبيانات GPS لا يمكن استرجاعها منها بعدها. وافتح الأداة في أي متصفح حديث: Chrome وFirefox وSafari وEdge تعمل، على الحاسوب والهاتف.</p>\n<p>وإذا لم تكن متأكدًا مما تحتويه صورتك، راجعها أولًا في <a href=\"/ar/arid-bayanat-as-sura/\">عارض البيانات الوصفية</a>: يُظهر كل وسم قبل أن تقرر ما تزيله.</p>\n<h2 id=\"step-1-open-the-tool\">الخطوة 1: افتح الأداة</h2>\n<p>اذهب إلى صفحة <a href=\"/ar/izala-bayanat-as-sura/\">إزالة البيانات الوصفية</a>: سترى مربع رفع وشرحًا موجزًا لما تفعله الأداة.</p>\n<p>لا شاشة تسجيل دخول ولا جدار دفع: الأداة مجانية، وتستطيع تنظيف صور غير محدودة دون علامات مائية أو رسوم. وعلى الهاتف، افتح الصفحة في Safari على iOS أو Chrome على Android: يتكيف التصميم، وتستطيع اختيار صور مباشرة من معرضك.</p>\n<p>احفظ الصفحة في المفضلة إذا نظفت صورًا كثيرًا: البائعون والصحفيون والآباء غالبًا يستخدمونها قبل كل نشر، فوجودها في متناول اليد يساعد.</p>\n<h2 id=\"step-2-upload-photos\">الخطوة 2: ارفع صورك</h2>\n<p>اسحب صورًا إلى مربع الرفع، أو انقر عليه لاختيار ملفات من جهازك: يمكنك إسقاط صورة واحدة أو دفعة كاملة دفعة واحدة. ويمكنك أيضًا اللصق بـCtrl+V على Windows أو Cmd+V على Mac: صورة منسوخة أو لقطة تسقط مباشرة في قائمة الرفع وتُنظف تلقائيًا.</p>\n<p>يبدأ التنظيف فورًا عند الرفع: لا زر بدء للضغط عليه ولا انتظار لخادم، لأن كل العمل يحدث داخل ذاكرة متصفحك. ويمكن أن يزن كل ملف حتى 20 MB: إذا كان ملف أكبر، اضغطه أولًا بـ<a href=\"/ar/\">ضاغط الصور</a> ثم نظف النسخة الأصغر.</p>\n<p>وفي لحظة تظهر بطاقة لكل صورة: تُظهر تلك البطاقة اسم الملف ونتيجة التنظيف وشارة التحقق.</p>\n<h2 id=\"step-3-check-badges\">الخطوة 3: راجع شارات التحقق</h2>\n<p>بعد الرفع، تُعاد تحليل كل بطاقة تلقائيًا وتُظهر كم وسم بيانات وصفية أُزيل، مثل Stripped X metadata tags to 0 remaining.</p>\n<p>شارة خضراء أو زمردية تعني أن الإخراج تُحقق منه كنظيف: تشغّل الأداة محلل البيانات الوصفية مرة ثانية على ملف الإخراج، فالشارة تحقق حقيقي لا وعد. وإذا أظهرت صورة Verified clean فور رفعها، فالمصدر كان يحتوي صفر وسوم EXIF أو GPS أو مقاطع نصية: لقطات الشاشة والصور المنزلة من تطبيقات مراسلة غالبًا نظيفة أصلًا.</p>\n<p>انتظر حتى تصبح الشارات خضراء على كل البطاقات قبل التنزيل: دفعة مكتملة فقط عندما تكون كل بطاقة متحققًا منها. وإذا أظهرت بطاقة وسومًا متبقية، يحتاج الملف تمريرة أخرى: غيّر طريقة التنظيف وانقر إعادة تنظيف الكل، كما هو موضح في الخطوة 5.</p>\n<h2 id=\"step-4-choose-method\">الخطوة 4: اختر طريقة التنظيف</h2>\n<p>الطريقة الافتراضية هي Lossless Binary Strip، وهي الخيار الصحيح لمعظم صور JPG وPNG: تزيل مقاطع البيانات الوصفية دون فك ترميز بكسل واحد أو إعادة ضغطه.</p>\n<p>أبقِ هذه الطريقة عندما تريد صفر تغيير في الجودة: يبقى JPG JPG ويبقى PNG PNG، وخلفيات PNG الشفافة تنجو بايتًا بايتًا. واختر Full Canvas Re-encode عندما تريد خريطة بتات جديدة تمامًا دون مقاطع موروثة: تُستخدم أيضًا تلقائيًا لمدخلات WebP وHEIC، وكلما غيّرت صيغة الإخراج.</p>\n<p>إعادة الترميز تصحح أيضًا الاتجاه: إذا بدا JPEG عمودي مائلًا بعد تنظيف دون فقدان، فوسم الاتجاه أُزيل دون تدوير البكسلات. وإعادة الترميز في لوحة جديدة تكتب البكسلات في الاتجاه الصحيح. والاختيار قابل للعكس قبل التنزيل: غيّر الطريقة وانقر إعادة تنظيف الكل، وتُعالج الدفعة مجددًا بالضبط الجديد.</p>\n<h2 id=\"step-5-format-quality\">الخطوة 5: اضبط صيغة الإخراج والجودة</h2>\n<p>افتراضيًا، تحافظ الأداة على الصيغة الأصلية، فيبقى JPG JPG ويبقى PNG PNG: هذا هو الخيار الأكثر أمانًا عندما تريد فقط أن تختفي البيانات الوصفية. وللتحويل أثناء التنظيف، اختر JPG أو PNG أو WebP في صيغة الإخراج: كل ملف يُعاد ترميزه نظيفًا عبر لوحة، مع إزالة كل البيانات الوصفية وتطبيق الصيغة المختارة.</p>\n<p>اضبط منزلق جودة إعادة الترميز بين 50 و100 بالمئة عندما تعيد الترميز: جودة قرب 85 بالمئة قيمة افتراضية جيدة لتصديرات WebP وJPG، بتوازن نظيف بين الحجم والحدة. ولا يفعل المنزلق شيئًا مع ملفات Lossless Binary Strip، لأنه لا يُعاد ترميز أي بكسل: ينطبق فقط على مدخلات WebP وHEIC، أو على تصديرات Full Canvas Re-encode.</p>\n<p>بعد تغيير أي ضبط، انقر إعادة تنظيف الكل: تُنظف الملفات فورًا عند إسقاطها بضبطك النشط، فالزر يطبق خياراتك المحدثة على الدفعة كلها. وللمقارنة الكاملة بين الطريقتين، اقرأ <a href=\"/ar/blog/dalil-izala-bayanat-as-suwar/\">دليل إزالة بيانات الصورة الكامل</a>.</p>\n<h2 id=\"step-6-download\">الخطوة 6: نزّل الملفات النظيفة</h2>\n<p>عندما تصبح الشارات خضراء، نزّل ملفاتك: انقر تنزيل نظيف على بطاقة فردية لحفظ تلك الصورة، أو تنزيل الكل نظيفًا (ZIP) للدفعة كلها.</p>\n<p>ملف ZIP اسمه clean_images_no_metadata.zip: يحفظ كل صورة نظيفة من الدفعة، جاهزة للرفع إلى متجر إلكتروني أو منتدى أو إعلان. والتنزيلات ملفات منفصلة: أصولك على القرص تبقى سليمة، لأن المتصفحات لا تستطيع الكتابة فوق ملفات في مجلداتك المحلية.</p>\n<p>احفظ الملفات النظيفة في مكان تستطيع تمييزها فيه عن الأصول، مثل مجلد اسمه clean أو ready-to-post: خلطها يبطل الغرض. وشارك النسخ النظيفة، لا الأصول: إذا رفعت الأصل خطأ، تذهب البيانات الوصفية معه.</p>\n<h2 id=\"step-7-verify\">الخطوة 7: تحقق من الملف النظيف</h2>\n<p>التحقق هو الخطوة التي يتخطاها معظم الناس، وهي الخطوة التي تثبت أن العمل تم: اسحب ملفًا نظيفًا منزّلًا إلى <a href=\"/ar/arid-bayanat-as-sura/\">عارض البيانات الوصفية</a>.</p>\n<p>إذا نجح التنظيف، يؤكد الإشعار الأخضر أنه لم تُكتشف وسوم EXIF أو GPS أو كاميرا مخفية، ولا يظهر أي تنبيه GPS: إنها مراجعة مستقلة لبايتات الملف، لا لادعاء الأداة. وإذا بقيت وسوم، يُظهر جدول العارض بالضبط أيها نجا: الناجون الشائعون مقاطع نص PNG وتعليقات JPEG، التي يتخطاها بعض المنظفات.</p>\n<p>وعند ظهور بقايا، عُد إلى أداة الإزالة وبدّل إلى Full Canvas Re-encode وانقر إعادة تنظيف الكل ونزّل مجددًا. ثم تحقق من الملف الجديد بنفس الطريقة. واجعل هذا عادة تمريرتين مع الصور الحساسة: راجع ونظف وأعد المراجعة. والمراجعة الثانية تستغرق ثوانٍ وتزيل كل شك.</p>\n<h2 id=\"cleaning-on-mobile\">إزالة البيانات الوصفية على الهاتف</h2>\n<p>معظم الصور تُشارك من الهاتف، فالسير يعمل في متصفحات الهاتف: افتح الأداة في Safari على iOS أو Chrome على Android واختر صورًا من معرضك.</p>\n<p>تُنظف الملفات عند رفعها وتصبح الشارات خضراء وتنزّل نسخًا نظيفة مباشرة إلى جهازك. ثم شارك الملفات النظيفة من معرضك. ونظف قبل فتح تطبيق التواصل الاجتماعي أو البيع، لا بعده: بمجرد نشر صورة، ربما نزل أي شخص الأصل ببياناته الوصفية سليمة.</p>\n<p>وإذا سجلت كاميرا هاتفك الموقع افتراضيًا، فكر في تعطيل الموقع لتطبيق الكاميرا: هذا يوقف وسوم GPS من المصدر، فالصور المستقبلية لا تحتاج تنظيفًا.</p>\n<h2 id=\"cleaning-batches\">تنظيف دفعات لمتاجر إلكترونية</h2>\n<p>يصور البائعون منتجات في المنزل، وقد تحمل تلك الصور إحداثيات GPS تشير مباشرة إلى عنوان البائع: التنظيف بالدفعة يزيل ذلك الخطر لجلسة كاملة.</p>\n<p>اسحب مجموعة صور الإعلان الكاملة وانتظر حتى تصبح الشارات خضراء على كل البطاقات. ثم انقر تنزيل الكل نظيفًا (ZIP) وارفع الملفات النظيفة إلى الإعلان. واستخدم نفس الروتين لمنشورات المنتديات وإعلانات الإيجار والإعلانات المبوبة: في أي مكان ينزّل فيه غرباء صورًا بدقة كاملة، تكون البيانات الوصفية خطرًا يستحق التنظيف.</p>\n<p>لا حد لعدد الملفات سوى حد 20 MB لكل ملف: مئة صورة لإعلان تُنظف بسهولة مثل صورة واحدة، دون علامات مائية أو سجلات أو رسوم. ولمعرفة مخاطر الخصوصية وراء هذا الروتين، اقرأ <a href=\"/ar/blog/makhatir-khususiyyat-as-suwar-gps-exif/\">خصوصية الصور: مخاطر GPS وEXIF والبيانات الوصفية</a>.</p>\n<h2 id=\"troubleshooting-removal\">حل المشاكل: عندما لا يخرج التنظيف كما توقعت</h2>\n<p>معظم المشاكل لها سبب بسيط: راجع القائمة التالية قبل افتراض أن الأداة مكسورة.</p>\n<p>وإذا استمرت مشكلة، جرّب أصلًا حديثًا من المعرض: هذا يخبرك إن كان السبب الملف أم الضبط.</p>\n<ul>\n<li>صورة تبدو مائلة بعد التنظيف: أزال التنظيف دون فقدان وسم اتجاه EXIF. بدّل إلى Full Canvas Re-encode وانقر إعادة تنظيف الكل لترك الاتجاه صحيحًا في البكسلات.</li>\n<li>ملف ما زال يُظهر وسومًا بعد التنظيف: بعض مقاطع نص PNG أو تعليقات JPEG قد تنجو من تمريرة أولى. جرّب Full Canvas Re-encode، الذي يعيد بناء الصورة من الصفر.</li>\n<li>منزلق الجودة يبدو لا يفعل شيئًا: ينطبق فقط على مدخلات WebP وHEIC، أو على تصديرات Full Canvas Re-encode. وLossless Binary Strip لا يعيد ترميز بكسلات أبدًا، فالمنزلق ليس له تأثير هناك.</li>\n<li>ملف لا يُرفع: راجع الحجم: الحد 20 MB لكل ملف. اضغط الصورة أولًا ثم نظف النسخة الأصغر.</li>\n<li>الملف المنزّل يبدو مطابقًا للأصل: هذا صحيح. التنظيف يزيل بيانات مخفية، لا بكسلات، فتنظيف ناجح يبدو مطابقًا للأصل تمامًا.</li>\n<li>الشارة تقول Verified clean فورًا: المصدر لم يكن له بيانات وصفية أصلًا، وهو شائع في لقطات الشاشة وصور تطبيقات المراسلة. لم يكن هناك شيء خطأ.</li>\n</ul>\n<h2 id=\"heic-photos\">إزالة البيانات الوصفية من صور HEIC</h2>\n<p>صور iPhone غالبًا تأتي كملفات HEIC، وتحتاج معالجة مختلفة قليلًا: تقبل الأداة رفع HEIC حتى 20 MB، مثل JPG وPNG.</p>\n<p>ملفات HEIC لا تُنظف بـLossless Binary Strip: بدلًا من ذلك، ترسم الأداة البكسلات على لوحة جديدة، ما يضمن إزالة كل ترويسات البيانات الوصفية. وهذا يعني أن تنظيف HEIC دائمًا إعادة ترميز: اضبط منزلق جودة إعادة الترميز قبل التنزيل: قرب 85 بالمئة قيمة افتراضية جيدة، و90 إلى 95 بالمئة أفضل للصور التي ستُطبع.</p>\n<p>ويمكنك أيضًا تحويل صورة HEIC أثناء تنظيفها: اختر JPG أو PNG أو WebP في صيغة الإخراج، وتصدّر الأداة نسخة نظيفة بالصيغة التي اخترتها. وتحويل HEIC إلى JPG خطوة شائعة قبل المشاركة، لأن JPG يفتح في كل مكان: يحدث التحويل والتنظيف في خطوة واحدة، فلا حاجة لتمريرة ثانية.</p>\n<p>بعد التنزيل، تحقق من النتيجة مثل أي ملف آخر: اسحب النسخة النظيفة إلى <a href=\"/ar/arid-bayanat-as-sura/\">عارض البيانات الوصفية</a> وأكّد الإشعار الأخضر.</p>\n<h2 id=\"after-downloading\">ماذا تفعل بعد التنزيل</h2>\n<p>تنزيل الملف النظيف ليس الخطوة الأخيرة: عادات صغيرة بعد التنزيل تضمن أن النسخة النظيفة هي التي تُشارك فعلًا.</p>\n<p>أولًا، راجع اسم الملف: قد يشارك التنزيل النظيف الاسم مع الأصل، فاحفظه في مجلد منفصل لئلا تختلط الاثنتان. وثانيًا، تحقق من ملف واحد على الأقل من كل دفعة: افتح النسخة النظيفة في العارض وأكّد الإشعار الأخضر بعدم وجود وسوم قبل رفعها إلى أي مكان.</p>\n<p>ثالثًا، احذف النسخ النظيفة من مجلد التنزيلات بمجرد نشرها، إذا عاشت الأصول في مكان آخر: نسخ نظيفة قديمة مختلطة مع أصول تسبب ارتباكًا لاحقًا. ورابعًا، إذا شاركت من الهاتف، تأكد من أن ورقة المشاركة اختارت الملف النظيف: قد تبدو تطبيقات المعرض متطابقة للأصول والنسخ النظيفة، فراجع التسمية قبل الإرسال.</p>\n<h2 id=\"how-to-remove-summary\">ملخص سريع</h2>\n<p>افتح أداة <a href=\"/ar/izala-bayanat-as-sura/\">إزالة البيانات الوصفية</a> واسحب صورك وانتظر شارات التحقق الخضراء. واختر Lossless Binary Strip لـJPG وPNG، أو Full Canvas Re-encode لـWebP وHEIC وتغييرات الصيغة والاتجاه.</p>\n<p>نزّل الملفات النظيفة أو ZIP، ثم تحقق من واحد في <a href=\"/ar/arid-bayanat-as-sura/\">عارض البيانات الوصفية</a>: عندما يظهر الإشعار الأخضر، تكون الصورة آمنة للمشاركة.</p>\n<p>الروتين كله يستغرق أقل من دقيقة: اجعله عادة قبل كل نشر، وستحمل صورك فقط ما قررت مشاركته.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كيف أزيل البيانات الوصفية من صورة على iPhone؟","answer":"افتح أداة إزالة البيانات الوصفية في Safari على الهاتف واختر الصورة من معرضك وانتظر شارة التحقق الخضراء. ثم المس تنزيل نظيف لحفظ النسخة النظيفة على جهازك. وشارك النسخة النظيفة لا الأصل."},{"question":"هل يمكنني إزالة البيانات الوصفية من لقطة شاشة؟","answer":"لقطات الشاشة غالبًا لا تحمل بيانات كاميرا وصفية أصلًا، لأن الحافظة تمرر بكسلات خام بدل الملف الأصلي للكاميرا. وعند سحب لقطة إلى الأداة، تُظهر الشارة Verified clean فورًا في أغلب الأحيان."},{"question":"ما أسرع طريقة لتنظيف صور كثيرة قبل أن يخرج إعلان مباشرًا؟","answer":"اسحب المجموعة كلها إلى الأداة دفعة واحدة وانتظر الشارات الخضراء على كل البطاقات وانقر تنزيل الكل نظيفًا (ZIP). ويحفظ ZIP كل صورة نظيفة في ملف واحد. وارفع الملفات النظيفة إلى الإعلان."},{"question":"هل أحتاج تنظيف صورة إذا أرسلتها فقط إلى صديق؟","answer":"يعتمد على القناة: تطبيقات مراسلة مثل WhatsApp تزيل البيانات الوصفية تلقائيًا، فصورة مرسلة عبرها غالبًا تصل نظيفة. ومرفقات البريد والنقل المباشر للملفات تحافظ على البيانات الوصفية، فنظف قبل إرسالها."},{"question":"لماذا صورتي النظيفة أخف وزنًا من الأصل؟","answer":"صور الكاميرا غالبًا تحمل مصغرات معاينة EXIF مضمنة وكتل XMP ومقاطع تعليقات: إزالتها في وضع Lossless Binary Strip غالبًا تقص عشرات الكيلوبايت دون أي تغيير في البكسلات."},{"question":"هل يمكنني التراجع عن إزالة البيانات الوصفية بعد تنزيل الملف النظيف؟","answer":"لا، النسخة النظيفة ليس لها بيانات وصفية لاستعادتها. ولهذا يجب أن تحفظ ملفك الأصلي في مجلد خاص قبل التنظيف. ويحتفظ الأصل بضبط الكاميرا وبيانات GPS لسجلاتك الخاصة."}];
